/**
 * @file md_recurrence.cuh
 * @brief McMurchie-Davidson Hermite recurrences and primitive integrals.
 *
 * The product of two Cartesian Gaussians centred at A and B is expanded in
 * Hermite Gaussians centred at the Gaussian product centre P,
 *
 *   exp(-a|r-A|^2) exp(-b|r-B|^2)
 *     = K exp(-mu |A-B|^2) sum_t E_t^{ij} Lambda_t(r-P),
 *   Lambda_t(r-P) = (d/dP)^t exp(-p |r-P|^2),
 *   p = a+b, P = (aA+bB)/p, mu = ab/p, K = exp(-mu |A-B|^2).
 *
 * The expansion coefficients E_t are generated by the one-dimensional
 * recurrence
 *
 *   E(i+1,j,t) = E(i,j,t-1)/(2p) + X_PA E(i,j,t) + (t+1) E(i,j,t+1)
 *   E(i,j+1,t) = E(i,j,t-1)/(2p) + X_PB E(i,j,t) + (t+1) E(i,j,t+1)
 *   E(0,0,0)   = K,
 *
 * applied independently in x, y and z and multiplied.
 *
 * The Hermite Coulomb auxiliary R_{tuv}(n) satisfies
 *
 *   R_{t+1,u,v}(n) = t R_{t-1,u,v}(n+1) + (P_x-C_x) R_{t,u,v}(n+1),
 *   R_{0,0,0}(n)   = (-2p)^n F_n(p |P-C|^2),
 *
 * and is generated downward in @c n so that only F_0..F_lmax are needed.
 */
#ifndef CUEST_MD_RECURRENCE_CUH
#define CUEST_MD_RECURRENCE_CUH

#include "../cuest_macros.h"
#include "boys.cuh"
#include "shell.cuh"

/** @brief Maximum number of 1-D Hermite coefficients stored per (i,j) table. */
constexpr int CUEST_E1D_TMAX = 8;
/** @brief Side of the 3-D Hermite Coulomb table (orders 0..8 per axis). */
constexpr int CUEST_RDIM = CUEST_MAX_LTOT + 1;

/** @brief Flat index into the 3-D Hermite Coulomb table. */
CUEST_HD inline int cuest_rindex(int tx, int ty, int tz) {
  return (tx * CUEST_RDIM + ty) * CUEST_RDIM + tz;
}

/** @brief Integer power, base^n for n >= 0. */
CUEST_HD inline double cuest_pow_int(double base, int n) {
  double r = 1.0;
  for (int k = 0; k < n; ++k)
    r *= base;
  return r;
}

/**
 * @brief Build the 1-D Hermite coefficient table E(ii,jj,t).
 *
 * The table has logical shape (imax+1) x (jmax+1) x CUEST_E1D_TMAX and is
 * stored flat with index ((ii*(jmax+1)+jj)*CUEST_E1D_TMAX + t).
 *
 * @param[in]  imax,jmax Highest angular momenta (each <= 3).
 * @param[in]  p         Sum of the two exponents.
 * @param[in]  PA        P_x - A_x.
 * @param[in]  PB        P_x - B_x.
 * @param[in]  K         Exponential prefactor (normally 1 for the table).
 * @param[out] tab       Flat table of size (imax+1)*(jmax+1)*CUEST_E1D_TMAX.
 */
template <typename T>
CUEST_HD void cuest_md_E1d_table(int imax, int jmax, T p, T PA, T PB, T K, T* tab) {
  const int nj = jmax + 1;
  for (int ii = 0; ii <= imax; ++ii)
    for (int jj = 0; jj <= jmax; ++jj)
      for (int t = 0; t < CUEST_E1D_TMAX; ++t)
        tab[(ii * nj + jj) * CUEST_E1D_TMAX + t] = T(0);

  tab[0] = K;
  for (int ii = 0; ii <= imax; ++ii) {
    for (int jj = 0; jj <= jmax; ++jj) {
      if (ii == 0 && jj == 0)
        continue;
      const T* a = (ii > 0) ? &tab[((ii - 1) * nj + jj) * CUEST_E1D_TMAX]
                            : &tab[(ii * nj + (jj - 1)) * CUEST_E1D_TMAX];
      const T x = (ii > 0) ? PA : PB;
      const int tmax = ii + jj;
      T* dst = &tab[(ii * nj + jj) * CUEST_E1D_TMAX];
      for (int t = 0; t <= tmax; ++t) {
        T v = x * a[t];
        if (t >= 1)
          v += a[t - 1] / (T(2) * p);
        v += T(t + 1) * a[t + 1];
        dst[t] = v;
      }
    }
  }
}

/**
 * @brief Extract E(i,j,0..i+j) for one pair of angular momenta.
 *
 * @param[out] E Array of at least i+j+1 entries.
 */
template <typename T>
CUEST_HD void cuest_md_E1d(int i, int j, T p, T PA, T PB, T K, T* E) {
  T tab[4 * 4 * CUEST_E1D_TMAX];
  cuest_md_E1d_table(i, j, p, PA, PB, K, tab);
  const int nj = j + 1;
  const T* src = &tab[(i * nj + j) * CUEST_E1D_TMAX];
  for (int t = 0; t <= i + j; ++t)
    E[t] = src[t];
}

/**
 * @brief Build the 3-D Hermite Coulomb table R(tx,ty,tz) at n = 0.
 *
 * @param[in]  lmax  Total Hermite order required (<= CUEST_MAX_LTOT).
 * @param[in]  alpha Effective exponent pq/(p+q) (or p for nuclear attraction).
 * @param[in]  D     Centre difference P - C (3 components).
 * @param[in]  Tval  alpha |P-C|^2.
 * @param[out] R     Table of CUEST_RDIM^3 entries, indexed by cuest_rindex().
 */
template <typename T>
CUEST_HD void cuest_md_Rtable(int lmax, T alpha, const T D[3], T Tval, T* R) {
  constexpr int N = CUEST_RDIM * CUEST_RDIM * CUEST_RDIM;
  T buf0[N];
  T buf1[N];
  T* next = buf0;
  T* cur = buf1;
  double F[CUEST_MAX_BOYS + 2];
  cuest_boys_vec(lmax, static_cast<double>(Tval), F);

  next[0] = T(cuest_pow_int(-2.0 * static_cast<double>(alpha), lmax)) * T(F[lmax]);
  for (int n = lmax - 1; n >= 0; --n) {
    const int lim = lmax - n;
    const T seed = T(cuest_pow_int(-2.0 * static_cast<double>(alpha), n)) * T(F[n]);
    for (int tx = 0; tx <= lim; ++tx) {
      for (int ty = 0; ty <= lim - tx; ++ty) {
        for (int tz = 0; tz <= lim - tx - ty; ++tz) {
          const int idx = cuest_rindex(tx, ty, tz);
          if (tx == 0 && ty == 0 && tz == 0) {
            cur[0] = seed;
          } else if (tx > 0) {
            T v = D[0] * next[cuest_rindex(tx - 1, ty, tz)];
            if (tx >= 2)
              v += T(tx - 1) * next[cuest_rindex(tx - 2, ty, tz)];
            cur[idx] = v;
          } else if (ty > 0) {
            T v = D[1] * next[cuest_rindex(tx, ty - 1, tz)];
            if (ty >= 2)
              v += T(ty - 1) * next[cuest_rindex(tx, ty - 2, tz)];
            cur[idx] = v;
          } else {
            T v = D[2] * next[cuest_rindex(tx, ty, tz - 1)];
            if (tz >= 2)
              v += T(tz - 1) * next[cuest_rindex(tx, ty, tz - 2)];
            cur[idx] = v;
          }
        }
      }
    }
    T* tmp = next;
    next = cur;
    cur = tmp;
  }
  for (int tx = 0; tx <= lmax; ++tx)
    for (int ty = 0; ty <= lmax - tx; ++ty)
      for (int tz = 0; tz <= lmax - tx - ty; ++tz)
        R[cuest_rindex(tx, ty, tz)] = next[cuest_rindex(tx, ty, tz)];
}

/**
 * @brief Primitive Cartesian overlap integral.
 *
 * @param[in] la,lb Angular components of the two Gaussians.
 * @param[in] p     a+b.
 * @param[in] PA    P-A (3 components).
 * @param[in] PB    P-B (3 components).
 * @param[in] K     Product exponential exp(-ab/p |A-B|^2).
 */
template <typename T>
CUEST_HD T cuest_prim_overlap(const int la[3], const int lb[3], T p, const T PA[3], const T PB[3],
                              T K) {
  T Ex[CUEST_E1D_TMAX], Ey[CUEST_E1D_TMAX], Ez[CUEST_E1D_TMAX];
  cuest_md_E1d(la[0], lb[0], p, PA[0], PB[0], T(1), Ex);
  cuest_md_E1d(la[1], lb[1], p, PA[1], PB[1], T(1), Ey);
  cuest_md_E1d(la[2], lb[2], p, PA[2], PB[2], T(1), Ez);
  const T s = T(sqrt(CUEST_PI / static_cast<double>(p)));
  return Ex[0] * Ey[0] * Ez[0] * K * s * s * s;
}

/**
 * @brief Primitive kinetic-energy integral.
 *
 * Evaluated in the manifestly symmetric form
 *
 *   T_ab = 1/2 int grad(phi_a) . grad(phi_b),
 *
 * expanding each derivative as
 *
 *   d_x (x-Ax)^l exp(-a(x-Ax)^2)
 *     = [ l (x-Ax)^(l-1) - 2a (x-Ax)^(l+1) ] exp(-a(x-Ax)^2),
 *
 * which is numerically identical to the second-derivative recurrence and
 * automatically includes the angular-lowering term for l >= 2.
 */
template <typename T>
CUEST_HD T cuest_prim_kinetic(const int la[3], const int lb[3], T a, T b, T p, const T PA[3],
                              const T PB[3], T K) {
  const int njd[3] = {lb[0] + 2, lb[1] + 2, lb[2] + 2};
  T tab[3][4 * 4 * CUEST_E1D_TMAX];
  for (int d = 0; d < 3; ++d)
    cuest_md_E1d_table(la[d] + 1, lb[d] + 1, p, PA[d], PB[d], T(1), tab[d]);

  const T s = T(sqrt(CUEST_PI / static_cast<double>(p)));
  const T pre = K * s * s * s;

  T tot = T(0);
  for (int d = 0; d < 3; ++d) {
    const int i0 = la[d];
    const int j0 = lb[d];
    const int pi[4] = {i0 - 1, i0 - 1, i0 + 1, i0 + 1};
    const int pj[4] = {j0 - 1, j0 + 1, j0 - 1, j0 + 1};
    const T coef[4] = {T(i0 * j0), T(-2) * b * T(i0), T(-2) * a * T(j0), T(4) * a * b};
    for (int m = 0; m < 4; ++m) {
      if (pi[m] < 0 || pj[m] < 0)
        continue;
      T val = T(1);
      for (int dd = 0; dd < 3; ++dd) {
        const int ii = (dd == d) ? pi[m] : la[dd];
        const int jj = (dd == d) ? pj[m] : lb[dd];
        val *= tab[dd][(ii * njd[dd] + jj) * CUEST_E1D_TMAX];
      }
      tot += coef[m] * val;
    }
  }
  return T(0.5) * pre * tot;
}

/**
 * @brief Primitive nuclear-attraction integral for one nucleus.
 *
 * @param[in] PC  P - C (3 components), C the nucleus position.
 * @param[in] Z   Nuclear charge.
 */
template <typename T>
CUEST_HD T cuest_prim_nuclear(const int la[3], const int lb[3], T p, const T PA[3], const T PB[3],
                              T K, const T PC[3], T Z) {
  T Ex[CUEST_E1D_TMAX], Ey[CUEST_E1D_TMAX], Ez[CUEST_E1D_TMAX];
  cuest_md_E1d(la[0], lb[0], p, PA[0], PB[0], T(1), Ex);
  cuest_md_E1d(la[1], lb[1], p, PA[1], PB[1], T(1), Ey);
  cuest_md_E1d(la[2], lb[2], p, PA[2], PB[2], T(1), Ez);

  const int lmax = la[0] + la[1] + la[2] + lb[0] + lb[1] + lb[2];
  const T Tval = p * (PC[0] * PC[0] + PC[1] * PC[1] + PC[2] * PC[2]);
  T R[CUEST_RDIM * CUEST_RDIM * CUEST_RDIM];
  cuest_md_Rtable<T>(lmax, p, PC, Tval, R);

  T sum = T(0);
  for (int tx = 0; tx <= la[0] + lb[0]; ++tx)
    for (int ty = 0; ty <= la[1] + lb[1]; ++ty)
      for (int tz = 0; tz <= la[2] + lb[2]; ++tz)
        sum += Ex[tx] * Ey[ty] * Ez[tz] * R[cuest_rindex(tx, ty, tz)];

  return -Z * (T(2) * T(CUEST_PI) / p) * K * sum;
}

#endif /* CUEST_MD_RECURRENCE_CUH */
